    expect(run(trailingSpec).stdout).toBe(trailingZeroSummary);
  });

  it('a citation written inside backticks reports nothing', () => {
    expect(run(trailingSpec).stdout).toBe(trailingZeroSummary);
  });

  it('a spec citing only in trailing parentheticals exits 0 with a zero summary', () => {
